{
  "primary_meaning": "burden-bearer or strong donkey that labors under loads (often linked to industrious service or voluntary servitude)",
  "primary_basis": [
    "Genesis 49:14-15"
  ],
  "alternatives": [
    {
      "meaning": "men who understand the times and know what Israel ought to do (discernment of seasons/strategy)",
      "basis": [
        "1 Chronicles 12:32"
      ],
      "prominence": "common"
    },
    {
      "meaning": "rejoicing in tents; calling peoples to the mountain for sacrifice; drawing abundance from seas and sand",
      "basis": [
        "Deuteronomy 33:18-19"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "wages/reward/recompense (from the name's etymology)",
      "basis": [
        "Genesis 30:18"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "medium",
  "notes": "Jacob's oracle in Gen 49 supplies the dominant traditional tribal emblem in Christian exposition of the twelve tribes; the Chronicles notice is widely preached in modern teaching but is not the primary symbolic assignment across historic interpretation. No single meaning is universally fixed."
}
